<script>
window.POS_EVENTS=@json($posEvents);
document.addEventListener('DOMContentLoaded',function(){
 const S={event:null,date:null,location:null,cart:[],customer:null,payment:'cash'};const q=s=>document.querySelector(s),money=n=>'₹'+Number(n||0).toLocaleString('en-IN',{minimumFractionDigits:2,maximumFractionDigits:2});
 const eventGrid=q('#eventGrid'),sessions=q('#sessions'),tickets=q('#tickets'),passes=q('#passes'),saleArea=q('#saleArea');
 function renderEvents(filter=''){eventGrid.innerHTML='';POS_EVENTS.filter(e=>e.title.toLowerCase().includes(filter.toLowerCase())).forEach(e=>{const x=document.createElement('div');x.className='event-card'+(S.event&&S.event.id===e.id?' active':'');x.innerHTML='<div class="event-img" style="background-image:url(\''+e.image+'\')"></div><div class="event-body"><div class="event-title">'+esc(e.title)+'</div><div class="event-meta">'+(e.date_type==='multiple'?e.dates.length+' sessions':esc((e.start_date||'')+' '+(e.start_time||'')))+' · '+e.tickets.length+' ticket groups</div></div>';x.onclick=()=>selectEvent(e);eventGrid.appendChild(x)})}
 function selectEvent(e){S.event=e;S.cart=[];S.location=e.locations[0]?.id||null;S.date=null;renderEvents(q('#eventSearch').value);renderPasses();renderSessions();renderTickets();renderCart();saleArea.style.display='block'}
 function renderSessions(){let ds=S.event.date_type==='multiple'?S.event.dates:[{value:(S.event.start_date||'')+' '+(S.event.start_time||''),label:(S.event.start_date||'')+' · '+(S.event.start_time||'')}];sessions.innerHTML='';ds.forEach((d,i)=>{const b=document.createElement('button');b.className='session'+((S.date===d.value||(!S.date&&i===0))?' active':'');b.textContent=d.label;b.onclick=()=>{S.date=d.value;renderSessions()};sessions.appendChild(b)});if(!S.date&&ds[0])S.date=ds[0].value}
 function renderPasses(){passes.innerHTML='';(S.event.passes||[]).forEach(p=>{const sold=p.inventory_type==='limited'&&Number(p.available)<=0,x=document.createElement('div');x.className='ticket-card';x.innerHTML='<div class="ticket-name">'+esc(p.name)+'</div><div class="ticket-price">'+money(p.price)+'</div><div class="ticket-stock">'+esc(p.pass_type.replaceAll('_',' '))+(p.inventory_type==='limited'?' · '+p.available+' available':' · Unlimited')+'</div><button class="ticket-add" '+(sold?'disabled':'')+'>'+(sold?'Sold out':'+ Add pass')+'</button>';if(!sold)x.onclick=()=>addPass(p);passes.appendChild(x)})}
 function addPass(p){let selected=p.date_ids||[];if(p.selection_mode==='choose_n'){const eligible=p.dates.map(d=>d.id+': '+d.label).join('\\n');const raw=prompt('Choose exactly '+p.choose_count+' date IDs, separated by commas:\\n'+eligible);if(!raw)return;selected=raw.split(',').map(Number).filter(Boolean);if(selected.length!==Number(p.choose_count))return alert('Select exactly '+p.choose_count+' dates.')}const key='pass|'+p.id+'|'+selected.join(',');let line=S.cart.find(x=>x.key===key);if(line)line.qty++;else S.cart.push({key:key,ticket_id:p.ticket_id,pass_product_id:p.id,event_date_ids:selected,variation:'',name:p.name,price:Number(p.price),qty:1});renderCart()}
 function renderTickets(){tickets.innerHTML='';S.event.tickets.forEach(t=>{if(t.pricing_type==='variation'&&t.variations.length){t.variations.forEach(v=>ticketCard(t,v))}else ticketCard(t,null)})}
 function ticketCard(t,v){const name=v?v.name:t.title,price=t.pricing_type==='free'?0:(v?v.price:t.price),at=v?v.available_type:t.available_type,av=v?v.available:t.available;const sold=at==='limited'&&Number(av)<=0,x=document.createElement('div');x.className='ticket-card';x.innerHTML='<div class="ticket-name">'+esc(name)+'</div><div class="ticket-price">'+(price?money(price):'FREE')+'</div><div class="ticket-stock">'+(at==='limited'?(av+' available'):'Unlimited')+'</div><button class="ticket-add" '+(sold?'disabled':'')+'>'+(sold?'Sold out':'+ Add ticket')+'</button>';if(!sold)x.onclick=()=>add(t,v,price,name);tickets.appendChild(x)}
 function add(t,v,price,name){const key=t.id+'|'+(v?v.name:'');let line=S.cart.find(x=>x.key===key);if(line)line.qty++;else S.cart.push({key:key,ticket_id:t.id,variation:v?v.name:'',name:name,price:Number(price),qty:1});renderCart()}
 function renderCart(){const box=q('#cartLines');if(!S.cart.length)box.innerHTML='<div class="cart-empty"><i class="fas fa-ticket-alt fa-3x mb-3"></i><br>Select tickets to start a sale</div>';else{box.innerHTML='';S.cart.forEach((l,i)=>{const d=document.createElement('div');d.className='cart-line';d.innerHTML='<div class="line-top"><span class="line-name">'+esc(l.name)+'</span><strong>'+money(l.price*l.qty)+'</strong></div><div class="line-controls"><button class="qty-btn" data-a="-">−</button><strong>'+l.qty+'</strong><button class="qty-btn" data-a="+">+</button><button class="remove-line"><i class="fas fa-trash"></i></button></div>';d.querySelector('[data-a="-"]').onclick=()=>{l.qty--;if(l.qty<1)S.cart.splice(i,1);renderCart()};d.querySelector('[data-a="+"]').onclick=()=>{l.qty++;renderCart()};d.querySelector('.remove-line').onclick=()=>{S.cart.splice(i,1);renderCart()};box.appendChild(d)})}const total=S.cart.reduce((a,l)=>a+l.price*l.qty,0),qty=S.cart.reduce((a,l)=>a+l.qty,0);q('#subtotal').textContent=money(total);q('#grandTotal').textContent=money(total);q('#payAmount').textContent=money(total);q('#paymentTotal').textContent=money(total);q('#mobileQty').textContent=qty;calcChange()}
 function modal(id,on=true){q('#'+id).classList.toggle('open',on)};document.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>modal(b.dataset.close,false));q('#customerOpen').onclick=()=>modal('customerModal');q('#mobileCart').onclick=()=>q('#cartPanel').classList.add('open');q('#closeCart').onclick=()=>q('#cartPanel').classList.remove('open');
 q('#saveCustomer').onclick=()=>{const n=q('#cName').value.trim(),p=q('#cPhone').value.trim();if(!n||!p)return alert('Customer name and phone are required.');S.customer={name:n,phone:p,email:q('#cEmail').value.trim(),age:q('#cAge').value,aadhaar:q('#cAadhaar').value.trim(),deliver:q('#cDeliver').checked};q('#customerLabel').textContent=n;q('#customerSub').textContent=p+(S.customer.email?' · '+S.customer.email:'');modal('customerModal',false)};
 q('#payOpen').onclick=()=>{if(!S.event||!S.cart.length)return alert('Add at least one ticket.');if(!S.customer)return modal('customerModal');modal('paymentModal')};document.querySelectorAll('.pay-method').forEach(b=>b.onclick=()=>{document.querySelectorAll('.pay-method').forEach(x=>x.classList.remove('active'));b.classList.add('active');S.payment=b.dataset.method;q('#cashBox').style.display=S.payment==='cash'?'block':'none'});
 function calcChange(){const total=S.cart.reduce((a,l)=>a+l.price*l.qty,0),cash=Number(q('#cashReceived').value||0);q('#changeDue').textContent=money(Math.max(0,cash-total))}q('#cashReceived').oninput=calcChange;
 q('#completeSale').onclick=()=>{if(!S.customer)return alert('Add customer details first.');if(!S.location)return alert('This event has no active Box Office counter.');const total=S.cart.reduce((a,l)=>a+l.price*l.qty,0);if(S.payment==='cash'&&Number(q('#cashReceived').value||0)<total)return alert('Cash received is less than the displayed ticket subtotal.');q('#fEvent').value=S.event.id;q('#fLocation').value=S.location;q('#fDate').value=S.date||'';q('#fName').value=S.customer.name;q('#fPhone').value=S.customer.phone;q('#fEmail').value=S.customer.email;q('#fAge').value=S.customer.age;q('#fAadhaar').value=S.customer.aadhaar;q('#fPayment').value=S.payment;q('#fCash').value=q('#cashReceived').value||'';q('#fDeliver').value=S.customer.deliver?1:0;const fd=q('#fItems');fd.innerHTML='';S.cart.forEach((l,i)=>{[['ticket_id',l.ticket_id],['quantity',l.qty],['variation',l.variation],['pass_product_id',l.pass_product_id||'']].forEach(([k,v])=>{const x=document.createElement('input');x.name='items['+i+']['+k+']';x.value=v;fd.appendChild(x)})});if(l.event_date_ids){l.event_date_ids.forEach((v,j)=>{const x=document.createElement('input');x.name='items['+i+'][event_date_ids]['+j+']';x.value=v;fd.appendChild(x)})}});const ad=q('#cAadhaarDoc'),ph=q('#cPhoto');if(ad.files.length){const dt=new DataTransfer();dt.items.add(ad.files[0]);q('#fAadhaarDoc').files=dt.files}if(ph.files.length){const dt=new DataTransfer();dt.items.add(ph.files[0]);q('#fPhoto').files=dt.files}q('#completeSale').disabled=true;q('#saleForm').submit()};
 q('#holdCart').onclick=async()=>{if(!S.event||!S.cart.length)return alert('Add tickets before holding a sale.');if(!S.location)return alert('This event has no active Box Office counter.');const customer=S.customer?S.customer:null;try{const res=await fetch('{{ route('organizer.boxoffice.holds.store') }}',{method:'POST',headers:{'Content-Type':'application/json','Accept':'application/json','X-CSRF-TOKEN':'{{ csrf_token() }}'},body:JSON.stringify({event_id:S.event.id,location_id:S.location,items:S.cart.map(l=>({ticket_id:l.ticket_id,quantity:l.qty,variation:l.variation||null})),customer:customer})});const data=await res.json();if(!res.ok)throw new Error(data.message||'Unable to hold cart.');S.cart=[];S.customer=null;q('#customerLabel').textContent='+ Add Customer';q('#customerSub').textContent='Name and phone required';renderCart();alert('Sale held. Hold #'+data.id+' expires at '+(data.expires_at||''));}catch(e){alert(e.message)}};q('#eventSearch').oninput=e=>renderEvents(e.target.value);q('#navEvents').onclick=()=>q('#eventSearch').focus();function esc(v){const d=document.createElement('div');d.textContent=v??'';return d.innerHTML}renderEvents();renderCart();
});
</script>
@endsection